/* Independent Web Audio effects. These are not Akai algorithm conversions. */
(()=>{
const names={off:'Aucun',echo:'Écho',reverb:'Réverbération',chorus:'Chorus',flanger:'Flanger',phaser:'Phaser',ring:'Ring Mod',lowpass:'Filtre passe-bas',highpass:'Filtre passe-haut',bandpass:'Filtre passe-bande',drive:'Saturation',crush:'Bitcrush',compressor:'Compresseur'};
function normalized(p={}){p=p&&typeof p==='object'?p:{};const clamp=(v,d)=>Number.isFinite(v)?Math.max(0,Math.min(1,v)):d;return {type:Object.hasOwn(names,p.type)?p.type:'off',amount:clamp(p.amount,.4),character:clamp(p.character,.35),wet:clamp(p.wet,.35)}}
function create(c,external,destination,initial){let nodes=[],oscillators=[],current=null,p=normalized(initial),input=c.createGain(),dry=c.createGain(),wet=c.createGain();external.connect(input);input.connect(dry).connect(destination);wet.connect(destination);const add=n=>(nodes.push(n),n),param=(a,v)=>a.setTargetAtTime(v,c.currentTime,.015);function clear(){for(const o of oscillators)try{o.stop()}catch{}oscillators=[];for(const n of nodes)n.disconnect();nodes=[];input.disconnect();input.connect(dry)}function build(){clear();const a=p.amount,b=p.character,t=p.type;let first,last;const filter=(type,f,q)=>{const n=add(c.createBiquadFilter());n.type=type;n.frequency.value=f;n.Q.value=q;return n};const lfo=(freq,depth,target)=>{const o=add(c.createOscillator()),g=add(c.createGain());o.frequency.value=freq;g.gain.value=depth;o.connect(g).connect(target);o.start();oscillators.push(o)};
if(t==='echo'){first=last=add(c.createDelay(1));first.delayTime.value=.03+.72*a;const fb=add(c.createGain());fb.gain.value=b*.8;first.connect(fb).connect(first);current={time:first.delayTime,feedback:fb.gain}}
else if(t==='reverb'){first=add(c.createConvolver());last=filter('lowpass',16000-14000*b,.7);first.connect(last);const duration=.25+3.75*a,len=Math.ceil(c.sampleRate*duration),ir=c.createBuffer(2,len,c.sampleRate);let seed=1701;for(let ch=0;ch<2;ch++){const d=ir.getChannelData(ch);for(let i=0;i<len;i++){seed=(Math.imul(seed,1664525)+1013904223)>>>0;d[i]=(seed/2147483648-1)*Math.pow(1-i/len,2.7)}}first.buffer=ir;current={tone:last.frequency}}
else if(t==='chorus'||t==='flanger'){first=last=add(c.createDelay(.1));first.delayTime.value=t==='chorus'?.02:.005;const depth=t==='chorus'?.001+.01*b:.0002+.003*b;const o=add(c.createOscillator()),g=add(c.createGain());o.frequency.value=.05+a*(t==='chorus'?3:2);g.gain.value=depth;o.connect(g).connect(first.delayTime);o.start();oscillators.push(o);if(t==='flanger'){const fb=add(c.createGain());fb.gain.value=.5;first.connect(fb).connect(first)}current={rate:o.frequency,depth:g.gain}}
else if(t==='phaser'){for(let i=0;i<4;i++){const f=filter('allpass',350+i*280,.7);if(last)last.connect(f);else first=f;last=f;lfo(.05+3*a,(200+300*i)*b,f.frequency)}current={}}
else if(t==='ring'){first=last=add(c.createGain());first.gain.value=1-b;const o=add(c.createOscillator()),g=add(c.createGain());o.frequency.value=20+1980*a;g.gain.value=b;o.connect(g).connect(first.gain);o.start();oscillators.push(o);current={rate:o.frequency,depth:g.gain,bias:first.gain}}
else if(['lowpass','highpass','bandpass'].includes(t)){first=last=filter(t,60*Math.pow(330,a),.2+16*b);current={cutoff:first.frequency,q:first.Q}}
else if(t==='drive'||t==='crush'){first=add(c.createWaveShaper());last=filter('lowpass',2000+18000*(1-b),.7);first.connect(last);const curve=new Float32Array(16384),drive=1+30*a,steps=Math.pow(2,2+Math.round(a*10));for(let i=0;i<curve.length;i++){const x=i/(curve.length-1)*2-1;curve[i]=t==='drive'?Math.tanh(x*drive)/Math.tanh(drive):Math.round(x*steps)/steps}first.curve=curve;first.oversample='none';current={tone:last.frequency}}
else if(t==='compressor'){first=last=add(c.createDynamicsCompressor());first.threshold.value=-6-42*a;first.ratio.value=1+19*b;first.knee.value=12;first.attack.value=.003;first.release.value=.25;current={threshold:first.threshold,ratio:first.ratio}}
else current={};if(first){input.connect(first);last.connect(wet)}}
let previousType=null,previousA=null,previousB=null;function set(settings){const first=previousType===null,next=normalized(settings),rebuild=next.type!==previousType||['reverb','drive','crush','phaser'].includes(next.type)&&(next.amount!==previousA||next.type==='phaser'&&next.character!==previousB);p=next;if(rebuild){build();previousType=p.type;previousA=p.amount;previousB=p.character}if(first){dry.gain.value=p.type==='off'?1:1-p.wet;wet.gain.value=p.type==='off'?0:p.wet}else{param(dry.gain,p.type==='off'?1:1-p.wet);param(wet.gain,p.type==='off'?0:p.wet)}const a=p.amount,b=p.character,t=p.type;if(t==='echo'){param(current.time,.03+.72*a);param(current.feedback,b*.8)}if(t==='reverb'||t==='drive'||t==='crush')param(current.tone,(t==='reverb'?16000:20000)-(t==='reverb'?14000:18000)*b);if(t==='chorus'||t==='flanger'){param(current.rate,.05+a*(t==='chorus'?3:2));param(current.depth,t==='chorus'?.001+.01*b:.0002+.003*b)}if(t==='ring'){param(current.rate,20+1980*a);param(current.depth,b);param(current.bias,1-b)}if(['lowpass','highpass','bandpass'].includes(t)){param(current.cutoff,60*Math.pow(330,a));param(current.q,.2+16*b)}if(t==='compressor'){param(current.threshold,-6-42*a);param(current.ratio,1+19*b)}}
set(p);return {set,dispose(){clear();try{external.disconnect(input)}catch{}input.disconnect();dry.disconnect();wet.disconnect()}}}
window.PocketFX={names,normalized,create};
})();
